const raw = $input.first().json;
const body = raw.body ?? raw;
const block = body.attachments?.[0]?.text ?? body;
const lines = [];

for (const d of block.new_devices || []) {
  const name = d['Device name'] || d.devName || 'Bilinmeyen';
  lines.push(`🆕 Yeni cihaz\n📛 ${name}\n🔧 ${d.MAC || d.eveMac || '?'}\n🌐 ${d.IP || d.eveIp || '?'}`);
}

for (const d of block.down_devices || []) {
  const name = d.devName || d['Device name'] || 'Bilinmeyen';
  lines.push(`🔴 Cihaz offline\n📛 ${name}\n🔧 ${d.eveMac || d.MAC || '?'}\n🌐 ${d.eveIp || d.IP || '?'}`);
}

for (const e of block.events || []) {
  const type = String(e['Event Type'] || e.eveEventType || '');
  if (!/disconnect|down|offline/i.test(type)) continue;
  const name = e['Device name'] || e.devName || 'Bilinmeyen';
  lines.push(`⚠️ ${type}\n📛 ${name}\n🔧 ${e.MAC || e.eveMac || '?'}\n🌐 ${e.IP || e.eveIp || '?'}`);
}

if (lines.length === 0) return [];

const panel = '__PANEL_PROTOCOL__://devices.__LAN_DOMAIN__';
const text = `📡 Pi Gateway — Ağ uyarısı\n\n${lines.join('\n\n')}\n\n🔗 ${panel}`;
return [{ json: { text } }];
